import * as T from './three.js';
export function bannerTexture(){const c=document.createElement('canvas');c.width=256;c.height=512;const x=c.getContext('2d');x.fillStyle='#631d19';x.fillRect(0,0,256,512);x.strokeStyle='#b69553';x.lineWidth=5;x.strokeRect(15,15,226,480);x.fillStyle='#b69553';x.font='bold 38px serif';x.textAlign='center';x.fillText('SPQR',128,366);for(let side of [-1,1]){for(let i=0;i<9;i++){x.beginPath();x.moveTo(128+side*12,198+i*5);x.lineTo(128+side*(98-i*5),145+i*13);x.lineTo(128+side*(86-i*5),172+i*12);x.closePath();x.fill()}x.beginPath();x.ellipse(128+side*37,283,8,36,side*.55,0,Math.PI*2);x.fill()}x.beginPath();x.ellipse(128,226,16,43,0,0,Math.PI*2);x.fill();x.beginPath();x.arc(128,183,13,0,Math.PI*2);x.fill();x.beginPath();x.moveTo(133,175);x.lineTo(153,186);x.lineTo(130,191);x.fill();for(let i=0;i<1500;i++){x.fillStyle=i%2?'#140e0922':'#dbb78b0c';x.fillRect((i*73)%256,(i*131)%512,1,12)}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
export function architectureDetails({world,stone,marble,bronze,leather,box,tube,column,fireBowl,mesh}){
// Ornament stays against the existing perimeter, outside collision/maneuver lanes.
for(let i=0;i<32;i++){let a=i*Math.PI/16,g=new T.Group();g.position.set(Math.sin(a)*33,0,Math.cos(a)*33);g.rotation.y=a;world.add(g);if(i%4){column(g,0,0,-.55,4.35,.23);box(g,marble,[0,4.45,-.55],[.9,.18,.85]);for(let s of [-1,1]){let scroll=mesh(g,new T.TorusGeometry(.12,.033,8,16,Math.PI*1.7),marble,[s*.22,4.2,-.82]);scroll.rotation.z=s*.3}}else{for(let s of [-1,1]){column(g,s*1.94,0,-1.05,4.55,.25);box(g,marble,[s*1.94,4.65,-1.05],[.9,.17,.9])}box(g,marble,[0,4.86,-1],[4.8,.28,1.1]);let sh=new T.Shape();sh.moveTo(-2.5,0);sh.lineTo(0,1.0);sh.lineTo(2.5,0);sh.closePath();mesh(g,new T.ExtrudeGeometry(sh,{depth:.42,bevelEnabled:true,bevelSize:.04,bevelThickness:.04,bevelSegments:2,steps:1}),stone,[0,5,-1.2]);for(let k=-2;k<=2;k++)box(g,bronze,[k*.29,4.86,-1.59],[.17,.14,.025]);}for(let j=-2;j<=2;j++)box(g,marble,[j*.48,4.62,-.9],[.16,.15,.35]);}
const wood=new T.MeshStandardMaterial({color:0x4e3929,map:leather.map,roughness:.94});
for(let i=0;i<10;i++){let a=.28+i*.63,g=new T.Group();g.position.set(Math.sin(a)*31.7,0,Math.cos(a)*31.7);g.rotation.y=a+.1;world.add(g);for(let j=0;j<6;j++)box(g,wood,[(j-2.5)*.2,.48,0],[.19,.95,.85]);for(let z of [-.43,.43])for(let y of [.12,.85])box(g,wood,[0,y,z],[1.3,.13,.1]);for(let x of [-.48,.48])box(g,bronze,[x,.48,-.49],[.065,.96,.025]);if(i%3===0){for(let s of [-1,1])tube(g,wood,[s*.95,0,.5],[s*.95,5.5,.5],.065);for(let h=1;h<5;h+=1.1){tube(g,wood,[-.95,h,.5],[.95,h,.5],.055);box(g,wood,[0,h,.7],[2.1,.08,.75])}tube(g,wood,[-.95,0,.5],[.95,5.2,.5],.04)}}
}
